import { useCallback, useState } from 'react';
import Task from './task';
import './dashboard.css';

function Dashboard({ user, userName, userRole, onLogout }) {
  const [activePage, setActivePage] = useState('Dashboard');
  const [search, setSearch] = useState('');
  const [taskStats, setTaskStats] = useState({ total: 0, completed: 0, remaining: 0 });

  const updateTaskStats = useCallback((stats) => setTaskStats(stats), []);
  const progress = taskStats.total ? Math.round((taskStats.completed / taskStats.total) * 100) : 0;
  const pages = [['Dashboard'], ['Tasks'], ['Projects'], ['Analytics'], ['Calendar']];

  return (
    <main className="dashboard-page">
      <div className="dashboard-shell">
        <aside className="dashboard-sidebar">
          <div className="product-logo"><span className="logo-icon"></span> Task Manager</div>
          <p className="menu-label">Menu</p>
          <nav aria-label="Main navigation">
            {pages.map(([page]) => (
              <button className={`nav-item ${activePage === page ? 'active' : ''}`} type="button" key={page} onClick={() => setActivePage(page)}><span></span>{page}</button>
            ))}
            {userRole !== 'User' && <button className={`nav-item ${activePage === 'Team Members' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Team Members')}><span></span>Team Members</button>}
            {userRole === 'Admin' && <button className={`nav-item ${activePage === 'Manage Users' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Manage Users')}><span></span>Manage Users</button>}
          </nav>
          <p className="menu-label general-label">General</p>
          <button className="nav-item" type="button" onClick={() => setActivePage('Settings')}><span></span>Settings</button>
          <button className="nav-item" type="button" onClick={onLogout}><span></span>Logout</button>
          <div className="upgrade-box"><strong>Task Manager</strong><p>Keep your work organized and on schedule.</p></div>
        </aside>

        <section className="dashboard-main">
          <header className="dashboard-topbar">
            <div><p className="dashboard-label">{activePage}</p><h1>Welcome back, {userName}!</h1><p>Here&apos;s what is happening with your tasks today.</p></div>
            <div className="topbar-actions"><label className="search-box"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks..." aria-label="Search tasks" /></label><div className="account-box"><span className="user-avatar">{userName.charAt(0).toUpperCase()}</span><span><strong>{userName}</strong><small>{userRole} account</small></span></div></div>
          </header>

          <Task search={search} compact={activePage === 'Dashboard'} onStats={updateTaskStats} assignedBy={userName} assignedTo={userName} assignedUserId={user?.id} />

          {activePage === 'Dashboard' && (
            <>
              <section className="metric-grid" aria-label="Task summary">
                <article className="metric-card blue"><strong>{taskStats.total}</strong><span>Total Tasks</span></article>
                <article className="metric-card green"><strong>{taskStats.completed}</strong><span>Completed</span></article>
                <article className="metric-card purple"><strong>{taskStats.remaining}</strong><span>Remaining</span></article>
                <article className="metric-card pink"><strong>{progress}%</strong><span>Progress</span></article>
              </section>
              <article className="panel progress-panel"><div className="panel-heading"><div><h2>Today&apos;s Progress</h2><p>Keep moving forward.</p></div></div><div className="progress-circle" style={{ '--progress': `${progress}%` }}><strong>{progress}%</strong></div><p>{progress === 100 ? 'All tasks completed!' : `${taskStats.remaining} tasks left to finish.`}</p></article>
            </>
          )}

          {activePage !== 'Dashboard' && activePage !== 'Tasks' && <section className="working-page panel"><p className="dashboard-label">Workspace</p><h2>{activePage}</h2><p>This section is ready for your {activePage.toLowerCase()}.</p></section>}
        </section>
      </div>
    </main>
  );
}

export default Dashboard;
